#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    size_t n = 5;
    int *squares = malloc(n * sizeof *squares);   /* n ints, contents undefined */
    if (squares == NULL) {
        fprintf(stderr, "out of memory\n");
        return 1;
    }
    for (size_t i = 0; i < n; i++) {
        squares[i] = (int)(i * i);
    }

    double *zeros = calloc(3, sizeof *zeros);     /* 3 doubles, all 0.0 */
    if (zeros == NULL) {
        free(squares);
        return 1;
    }

    for (size_t i = 0; i < n; i++) {
        printf("%d%s", squares[i], i + 1 < n ? " " : "\n");
    }
    printf("%.1f %.1f %.1f\n", zeros[0], zeros[1], zeros[2]);

    free(squares);
    free(zeros);
    squares = NULL;     /* a freed pointer must not be used again */
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    size_t capacity = 2, count = 0;
    int *items = malloc(capacity * sizeof *items);
    if (items == NULL) return 1;

    for (int value = 1; value <= 9; value++) {
        if (count == capacity) {
            size_t bigger = capacity * 2;
            int *tmp = realloc(items, bigger * sizeof *items);
            if (tmp == NULL) {
                free(items);           /* the old block is still ours */
                return 1;
            }
            items = tmp;
            capacity = bigger;
            printf("capacity grew to %zu\n", capacity);
        }
        items[count++] = value * value;
    }

    printf("%zu items, last = %d\n", count, items[count - 1]);
    free(items);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char *copy_string(const char *src)      /* caller must free the result */
{
    size_t len = strlen(src) + 1;       /* include the terminator */
    char *dst = malloc(len);
    if (dst != NULL) {
        memcpy(dst, src, len);
    }
    return dst;
}

int main(void)
{
    char *greeting = copy_string("hello");
    if (greeting == NULL) return 1;

    greeting[0] = 'H';                  /* heap memory is writable */
    printf("%s (%zu bytes allocated)\n", greeting, strlen(greeting) + 1);
    free(greeting);
    return 0;
}

